using System;using System.Linq;using NUnit.Framework;using UnityEditor;using UnityEngine;using UnityEngine.Tilemaps;using Rootborn.Game.Placement;using UnityEditor.AddressableAssets;
namespace Rootborn.Tests.EditMode.Placement{public sealed class GrowthRoomArtAssetTests{
[TestCase("Assets/Art/StudentLifePixels/Furniture48/StudentLife_toy_kitchen_2x1.png",96,192,24,24)]
[TestCase("Assets/Art/CareerFurniture/Growth31/Growth31_first_aid_play_set_1x1.png",48,144,24,24)]
[TestCase("Assets/Art/CareerFurniture/Growth31/Growth31_assembly_desk_2x1.png",96,144,24,24)]
[TestCase("Assets/Art/CareerFacilities/Supplement/training_poster.png",96,144,48,4)]
public void AuthoredSpriteUsesPixelSamplingAndPlacementPivot(string path,int width,int height,int px,int py){var s=AssetDatabase.LoadAssetAtPath<Sprite>(path);Assert.That(s,Is.Not.Null,path);Assert.That(s.rect.size,Is.EqualTo(new Vector2(width,height)));Assert.That(s.pivot,Is.EqualTo(new Vector2(px,py)));Assert.That(s.pixelsPerUnit,Is.EqualTo(48));var i=(TextureImporter)AssetImporter.GetAtPath(path);Assert.That(i.filterMode,Is.EqualTo(FilterMode.Point));Assert.That(i.mipmapEnabled,Is.False);Assert.That(i.textureCompression,Is.EqualTo(TextureImporterCompression.Uncompressed));var e=AddressableAssetSettingsDefaultObject.Settings.FindAssetEntry(AssetDatabase.AssetPathToGUID(path));Assert.That(e,Is.Not.Null);}
[TestCase("first_aid_play_set",1)][TestCase("assembly_desk",2)]public void SavedFurnitureHasCompleteFootprintAndSpriteDependency(string name,int width){string path="Assets/Data/Interiors/Furniture/Growth31/Furniture_Growth31_"+name+".asset";var f=AssetDatabase.LoadAssetAtPath<FurnitureDefinition>(path);Assert.That(f,Is.Not.Null);Assert.That(f.FootprintCells.Count,Is.EqualTo(width));Assert.That(f.TileParts.Count,Is.EqualTo(1));var tile=f.TileParts[0].Tile as Tile;Assert.That(tile,Is.Not.Null);Assert.That(tile.sprite,Is.Not.Null);Assert.That(f.AllowedSurfaceIds,Does.Contain("house"));Assert.That(f.DisplayName,Does.Not.Contain("Growth31"));var e=AddressableAssetSettingsDefaultObject.Settings.FindAssetEntry(AssetDatabase.AssetPathToGUID(path));Assert.That(e,Is.Not.Null);}
}}
